        def ok(n):
            T = 0
            for b in range(20):
                A = (n >> (b + 1)) << b
                r = n & ((1 << (b + 1)) - 1)
                A += max(0, r - (1 << b))
                T += 2 * A * n - A * A
            return n * (n - 1) // 2 * T <= s
        lo, hi = 1, 20000
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid): lo = mid
            else: hi = mid - 1
