class Solution {
public:
    bool ok(long long n, long long s) {
        long long T = 0;
        for (int b = 0; b < 20; b++) {
            long long A = (n >> (b + 1)) << b;
            long long r = n & ((1LL << (b + 1)) - 1);
            A += max(0LL, r - (1LL << b));
            T += 2 * A * n - A * A;
        }
        return (__int128)n * (n - 1) / 2 * T <= s;
    }
    int maxSizedArray(long long s) {
        long long lo = 1, hi = 20000;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (ok(mid, s)) lo = mid; else hi = mid - 1;
        }
        return (int)lo;
    }
};

